<script setup>
import Updates from './Updates.vue';
import appMeta from '../package.json';
import { ref, computed, onMounted, onUnmounted, watch, nextTick } from 'vue';
import { Anchor, LayoutDashboard, Files, Waves, SlidersHorizontal, Server, ScrollText, Settings, ArrowDown, ArrowUp, Plus, RefreshCw, ChevronRight, ArrowUpRight, MoreHorizontal, Search, X, Check, CircleHelp, Wifi, WifiOff, ShieldCheck, FlaskConical, Play, Pause, LogOut, Pencil, Trash2, Clock3, Eye, Download, Tag, Zap, AlertTriangle, CheckCircle2, Menu, CheckCheck, Link2, LockKeyhole, Layers3, Activity, Sun, Moon } from 'lucide-vue-next';

const M=1048576;
const theme=ref(localStorage.getItem('harbor-theme')||'dark');
watch(theme,value=>{document.documentElement.dataset.theme=value;localStorage.setItem('harbor-theme',value);},{immediate:true});
function toggleTheme(){theme.value=theme.value==='dark'?'light':'dark';}
const page=ref('overview'), mobileNav=ref(false), auth=ref(null), pass=ref(''), authBusy=ref(false), authError=ref('');
const data=ref(null), toast=ref(null), loading=ref(false), modal=ref(null), form=ref({}), saving=ref(false), modalError=ref(''), preview=ref(null), selected=ref([]);
const query=ref(''), stateFilter=ref(''), clientFilter=ref(''), hostFilter=ref(''), poolFilter=ref(''), tagFilter=ref(''), listPage=ref(1);
let timer, toastTimer, lastFocus;
watch(modal, async (value, previous)=>{if(value&&!previous)lastFocus=document.activeElement;await nextTick();if(value)document.querySelector('.modal input:not([disabled]), .modal select, .modal button')?.focus();else if(previous)lastFocus?.focus();});
function modalKeys(e){if(!modal.value)return;if(e.key==='Escape'&&!saving.value){modal.value=null;return;}if(e.key==='Tab'){const nodes=[...document.querySelectorAll('.modal button:not([disabled]), .modal input:not([disabled]), .modal select:not([disabled])')].filter(n=>n.offsetParent!==null);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}}
const nav=[{id:'overview',label:'传输总览',icon:LayoutDashboard},{id:'torrents',label:'所有种子',icon:Files},{id:'pools',label:'带宽池',icon:Waves},{id:'rules',label:'自动化规则',icon:SlidersHorizontal},{id:'clients',label:'下载器',icon:Server},{id:'activity',label:'运行记录',icon:ScrollText},{id:'updates',label:'版本更新',icon:Download}];
const title=computed(()=>[...nav,{id:'settings',label:'设置'}].find(n=>n.id===page.value)?.label || '总览');
const torrents=computed(()=>data.value?.torrents||[]), clients=computed(()=>data.value?.clients||[]), plans=computed(()=>data.value?.plan||[]), pools=computed(()=>data.value?.pools||[]), rules=computed(()=>data.value?.rules||[]);
const demo=computed(()=>data.value?.settings.mode==='demo'), controlled=computed(()=>data.value?.settings.controlEnabled);
const up=computed(()=>clients.value.reduce((s,c)=>s+c.upload,0)), down=computed(()=>clients.value.reduce((s,c)=>s+c.download,0));
const active=computed(()=>torrents.value.filter(t=>t.online&&t.upload+t.download>0).length);
const online=computed(()=>clients.value.filter(c=>c.online).length);
const allTags=computed(()=>[...new Set(torrents.value.flatMap(t=>t.tags))].sort());
const allHosts=computed(()=>[...new Set(torrents.value.flatMap(t=>t.hosts))].sort());
const filtered=computed(()=>torrents.value.filter(t=>(!query.value||[t.name,t.clientName,...t.tags,...t.hosts].join(' ').toLowerCase().includes(query.value.toLowerCase()))&&(!stateFilter.value||t.state===stateFilter.value)&&(!clientFilter.value||t.clientId===clientFilter.value)&&(!hostFilter.value||t.hosts.includes(hostFilter.value))&&(!tagFilter.value||t.tags.includes(tagFilter.value))&&(!poolFilter.value||plan(t.key)?.poolId===poolFilter.value)));
const visible=computed(()=>filtered.value.slice((listPage.value-1)*25,listPage.value*25));
const topTorrents=computed(()=>[...torrents.value].sort((a,b)=>(b.upload+b.download)-(a.upload+a.download)).slice(0,5));
const events=computed(()=>data.value?.events||[]);
const conflicts=computed(()=>data.value?.managed.filter(m=>m.conflict)||[]);
const explanation=computed(()=>modal.value?.kind==='explain'?torrents.value.find(t=>t.key===modal.value.key):null);
const chartRange=ref(30);
const history=computed(()=>{
  const rows=(data.value?.history||[]).filter(p=>p.time>Date.now()-chartRange.value*60000);
  if(rows.length>20||!demo.value) return rows;
  return Array.from({length:60},(_,i)=>({time:Date.now()-(59-i)*10000,upload:up.value*(.65+.2*Math.sin(i*.26)+.1*Math.sin(i*.81)),download:down.value*(.75+.15*Math.sin(i*.2)+.14*Math.cos(i*.56))}));
});
const chartMax=computed(()=>Math.max(10*M,...history.value.flatMap(p=>[p.upload,p.download]))*1.2);
function chartPath(dir,area=false){const h=history.value;if(!h.length)return '';const xy=h.map((p,i)=>`${(i/Math.max(h.length-1,1)*850).toFixed(1)},${(170-p[dir]/chartMax.value*155).toFixed(1)}`);return `M${xy.join(' L')}${area?' L850,185 L0,185 Z':''}`;}
const chartTimes=computed(()=>history.value.length ? [history.value[0],history.value[Math.floor(history.value.length/2)],history.value.at(-1)].map(p=>time(p.time,true)) : ['等待采样','','']);
const states={downloading:'下载中',seeding:'做种中',paused:'已暂停',stalled:'等待连接',checking:'校验中',error:'异常'};
const format=(v,unit=true)=>{if(v==null)return unit?'不限速':'—';if(!Number.isFinite(Number(v)))return '—';if(v<1024)return `${Math.round(v)}${unit?' B/s':''}`;if(v<M)return `${(v/1024).toFixed(v<10240?1:0)}${unit?' KiB/s':''}`;return `${(v/M).toFixed(1)}${unit?' MiB/s':''}`;};
const bytes=v=>v>=1024**3?`${(v/1024**3).toFixed(1)} GiB`:`${(v/M).toFixed(1)} MiB`;
const time=(v,short=false)=>v?new Intl.DateTimeFormat('zh-CN',{timeZone:data.value?.settings.timezone||'Asia/Shanghai',hour:'2-digit',minute:'2-digit',...(short?{}:{second:'2-digit'}),hourCycle:'h23'}).format(new Date(v)):'—';
const date=computed(()=>new Intl.DateTimeFormat('zh-CN',{timeZone:data.value?.settings.timezone||'Asia/Shanghai',month:'long',day:'numeric',weekday:'long'}).format(new Date()));
const planMap=computed(()=>new Map(plans.value.map(p=>[p.key,p])));
const plan=key=>planMap.value.get(key);
const busyPools=computed(()=>[...pools.value].sort((a,b)=>(poolStats(b.id).upload+poolStats(b.id).download)-(poolStats(a.id).upload+poolStats(a.id).download)).slice(0,3));
function poolStats(id){const keys=new Set(plans.value.filter(p=>p.poolId===id).map(p=>p.key));const rows=torrents.value.filter(t=>keys.has(t.key));return {count:rows.length,upload:rows.filter(t=>t.online).reduce((s,t)=>s+t.upload,0),download:rows.filter(t=>t.online).reduce((s,t)=>s+t.download,0),allocated:plans.value.filter(p=>p.poolId===id).reduce((s,p)=>s+(p.upload||0),0)};}
function notify(message,error=false){toast.value={message,error};clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value=null,5500);}
async function api(path,method='GET',body,attempt=0){const response=await fetch(`/api/${path}`,{method,headers:body!==undefined?{'Content-Type':'application/json'}:{},...(body!==undefined?{body:JSON.stringify(body)}:{})});const value=await response.json();if(!response.ok){if(response.status===401&&path!=='auth/login'){auth.value={setup:false,authenticated:false};data.value=null;}if(response.status===409&&value.error?.startsWith('正在同步')&&attempt<5){await new Promise(r=>setTimeout(r,700));return api(path,method,body,attempt+1);}throw new Error(value.error||'请求失败');}return value;}
async function load(){if(!auth.value?.authenticated)return;try{data.value=await api('state');}catch(e){if(auth.value?.authenticated)notify(e.message,true);}}
async function login(){authBusy.value=true;authError.value='';try{await api(auth.value.setup?'auth/setup':'auth/login','POST',{password:pass.value});auth.value={setup:false,authenticated:true};pass.value='';await load();}catch(e){authError.value=e.message;}finally{authBusy.value=false;}}
async function logout(){try{await api('auth/logout','POST',{});auth.value={setup:false,authenticated:false};data.value=null;}catch(e){notify(e.message,true);}}
function navigate(id){page.value=id;mobileNav.value=false;selected.value=[];listPage.value=1;}
async function refresh(){loading.value=true;try{data.value=await api('refresh','POST',{});notify('传输状态已更新');}catch(e){notify(e.message,true);}finally{loading.value=false;}}
async function patchSettings(patch){try{await api('settings','PUT',patch);await load();notify('运行设置已保存');}catch(e){notify(e.message,true);}}
function switchMode(){modal.value={kind:'mode'};modalError.value='';}
async function toggleControl(){if(!controlled.value){modal.value={kind:'control'};modalError.value='';}else await patchSettings({controlEnabled:false});}
async function release(){saving.value=true;modalError.value='';try{const result=await api('release','POST',{});await load();notify(result.remaining?`已停止接管，${result.remaining} 项因失联或外部修改保留，请查看任务详情`:'已释放接管，恢复接管前设置',!!result.remaining);modal.value=null;}catch(e){modalError.value=e.message;}finally{saving.value=false;}}
function open(kind,item){preview.value=null;modalError.value='';modal.value={kind,id:item?.id};
  if(kind==='client')form.value={name:item?.name||'',type:item?.type||'qb',url:item?.url||'',username:item?.username||'',password:'',enabled:item?.enabled??true,hasPassword:item?.hasPassword};
  if(kind==='pool')form.value={name:item?.name||'',upload:item?.upload==null?'':item.upload/M,download:item?.download==null?'':item.download/M,weight:item?.weight||1,color:item?.color||'#218575'};
  if(kind==='rule')form.value={name:item?.name||'',enabled:item?.enabled??true,priority:item?.priority??50,clients:[...(item?.clients||[])],hosts:(item?.hosts||[]).join(', '),tags:(item?.tags||[]).join(', '),category:item?.category||'',states:[...(item?.states||[])],poolId:item?.poolId||'',upload:item?.upload==null?'':item.upload/M,download:item?.download==null?'':item.download/M,weight:item?.weight||1,scheduled:!!item?.schedule,start:item?.schedule?.start||'08:00',end:item?.schedule?.end||'23:00',days:[...(item?.schedule?.days||[])]};
  if(kind==='labels')form.value={tags:selected.value.length===1?(torrents.value.find(t=>t.key===selected.value[0])?.localTags||[]).join(', '):''};
  if(kind==='override')form.value={upload:'',download:'',weight:3,minutes:30};
}
const split=v=>String(v||'').split(/[,，\n]/).map(s=>s.trim()).filter(Boolean);
const limitInput=v=>v===''||v==null?null:Number(v)*M;
function rulePayload(){const f=form.value;return {...f,hosts:split(f.hosts),tags:split(f.tags),upload:limitInput(f.upload),download:limitInput(f.download),priority:Number(f.priority),weight:Number(f.weight),schedule:f.scheduled?{start:f.start,end:f.end,days:f.days}:null};}
async function previewRule(){saving.value=true;modalError.value='';try{preview.value=await api('preview','POST',{...rulePayload(),id:modal.value.id});}catch(e){modalError.value=e.message;}finally{saving.value=false;}}
async function testClient(){saving.value=true;modalError.value='';try{const result=await api('clients/test','POST',{...form.value,id:modal.value.id});preview.value={connection:`连接成功 · ${result.version} · ${result.torrents} 个种子`};}catch(e){modalError.value=e.message;}finally{saving.value=false;}}
async function saveModal(){saving.value=true;modalError.value='';try{const {kind,id}=modal.value;const f=form.value;
  if(kind==='client')await api(`clients${id?'/'+id:''}`,id?'PUT':'POST',f);
  if(kind==='pool')await api(`pools${id?'/'+id:''}`,id?'PUT':'POST',{...f,upload:limitInput(f.upload),download:limitInput(f.download),weight:Number(f.weight)});
  if(kind==='rule')await api(`rules${id?'/'+id:''}`,id?'PUT':'POST',rulePayload());
  if(kind==='labels')await api('labels','PUT',{keys:selected.value,tags:split(f.tags)});
  if(kind==='override')await api('override','POST',{...f,keys:selected.value,upload:limitInput(f.upload),download:limitInput(f.download),weight:Number(f.weight),minutes:Number(f.minutes)});
  if(kind==='control')await api('settings','PUT',{controlEnabled:true});
  if(kind==='mode')await api('settings','PUT',{mode:demo.value?'real':'demo'});
  if(kind==='delete')await api(`${modal.value.collection}/${id}`,'DELETE');
  if(kind==='settings')await api('settings','PUT',{...f,uploadBudget:limitInput(f.uploadBudget),downloadBudget:limitInput(f.downloadBudget),pollSeconds:Number(f.pollSeconds),controlSeconds:Number(f.controlSeconds)});
  if(kind==='password')await api('auth/password','POST',f);
  modal.value=null;selected.value=[];await load();notify('已保存');
}catch(e){modalError.value=e.message;}finally{saving.value=false;}}
function editSettings(){modal.value={kind:'settings'};modalError.value='';const s=data.value.settings;form.value={uploadBudget:s.uploadBudget==null?'':s.uploadBudget/M,downloadBudget:s.downloadBudget==null?'':s.downloadBudget/M,pollSeconds:s.pollSeconds,controlSeconds:s.controlSeconds,timezone:s.timezone,demandAware:s.demandAware??true};}
function confirmDelete(collection,item){modal.value={kind:'delete',collection,id:item.id,name:item.name};modalError.value='';}
async function toggleRule(r){try{await api(`rules/${r.id}`,'PUT',{...r,enabled:!r.enabled});await load();notify(r.enabled?'规则已停用':'规则已启用');}catch(e){notify(e.message,true);}}
function explain(t){modal.value={kind:'explain',key:t.key};modalError.value='';}
async function reclaim(key){saving.value=true;try{await api('reclaim','POST',{key});await load();notify('已重新接管，下一轮按规则调整');}catch(e){modalError.value=e.message;}finally{saving.value=false;}}
async function clearOverride(key){try{await api('override','POST',{keys:[key],clear:true});await load();notify('临时设置已取消');}catch(e){notify(e.message,true);}}
async function exportConfig(){try{const config=await api('export');const url=URL.createObjectURL(new Blob([JSON.stringify(config,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`torrent-harbor-config-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(url);notify('配置已导出，不含密码；完整备份请保存 data 目录');}catch(e){notify(e.message,true);}}
function selectAll(){selected.value=visible.value.every(t=>selected.value.includes(t.key))?selected.value.filter(k=>!visible.value.some(t=>t.key===k)):[...new Set([...selected.value,...visible.value.map(t=>t.key)])];}
const modalTitle=computed(()=>({client:modal.value?.id?'编辑下载器':'连接一个下载器',pool:modal.value?.id?'编辑带宽池':'创建带宽池',rule:modal.value?.id?'编辑自动化规则':'创建自动化规则',labels:'设置本地标签',override:'临时调整带宽',explain:'限速解释',mode:'切换运行环境',control:'开启自动接管',release:'释放接管并恢复',delete:'删除配置',settings:'带宽与调度设置',password:'修改管理密码'}[modal.value?.kind]||''));
onMounted(async()=>{window.addEventListener('keydown',modalKeys);try{auth.value=await api('auth/status');if(auth.value.authenticated)await load();}catch(e){authError.value=e.message;}timer=setInterval(load,4000);});
onUnmounted(()=>{window.removeEventListener('keydown',modalKeys);clearInterval(timer);clearTimeout(toastTimer);});
</script>

<template>
  <div v-if="!auth || (auth.authenticated&&!data)" class="initial"><Anchor :size="34"/><p>正在整理你的带宽…</p></div>
  <div v-else-if="!auth.authenticated" class="auth-shell">
    <div class="auth-story"><div class="brand"><span class="brand-symbol"><Anchor :size="25"/></span><span>Torrent Harbor<small>种子港 · 带宽管理</small></span></div><div class="auth-copy"><span class="eyebrow">A CALMER WAY TO TORRENT</span><h1>让每一份带宽，<br>各得其所。</h1><p>把下载器、Tracker 和标签连接起来。<br>从此，传输有序，掌控从容。</p><div class="orbit-art"><div class="orbit o1"></div><div class="orbit o2"></div><div class="orbit o3"></div><span class="orbit-center"><Anchor :size="48"/></span><span class="orbit-node n1"><Server :size="24"/></span><span class="orbit-node n2"><Waves :size="24"/></span><span class="orbit-node n3"><Tag :size="24"/></span></div></div><small>LOCAL FIRST · YOUR NETWORK, YOUR RULES</small></div>
    <form class="auth-card" @submit.prevent="login"><span class="auth-icon"><LockKeyhole :size="25"/></span><span class="eyebrow">WELCOME TO YOUR HARBOR</span><h2>{{auth.setup?'准备好，启航。':'欢迎回到种子港'}}</h2><p>{{auth.setup?'设置管理密码，开始管理你的下载器。':'输入管理密码，查看你的传输工作空间。'}}</p><label>管理密码<input v-model="pass" type="password" :minlength="auth.setup?10:1" maxlength="256" :autocomplete="auth.setup?'new-password':'current-password'" placeholder="至少 10 个字符" required autofocus></label><p v-if="authError" class="form-error">{{authError}}</p><button class="btn primary wide" :disabled="authBusy">{{authBusy?'正在进入…':auth.setup?'创建工作空间':'进入工作空间'}}<ArrowUpRight :size="17"/></button><div class="auth-note"><ShieldCheck :size="16"/>首次进入提供独立演示环境，可随时连接真实下载器。</div></form>
  </div>
  <div v-else class="app-shell">
    <div v-if="mobileNav" class="nav-backdrop" @click="mobileNav=false"></div>
    <aside class="sidebar" :class="{open:mobileNav}">
      <a class="brand" href="#" @click.prevent="navigate('overview')"><span class="brand-symbol"><Anchor :size="25"/></span><span>Torrent Harbor<small>种子港 · 带宽管理</small></span></a>
      <div class="workspace-label">工作空间 <span>PERSONAL</span></div>
      <nav><button v-for="n in nav" :key="n.id" :class="{active:page===n.id}" @click="navigate(n.id)"><component :is="n.icon" :size="19"/><span>{{n.label}}</span><span v-if="n.id==='torrents'" class="nav-count">{{torrents.length}}</span><span v-if="n.id==='rules'" class="nav-dot"></span></button></nav>
      <div class="sidebar-bottom"><div class="harbor-status"><span class="status-beacon"></span><div>{{controlled?'自动调度运行中':'只读预览运行中'}}<small>{{demo?'演示数据 · 与真实环境隔离':'真实环境 · 本地运行'}}</small></div><Activity :size="17"/></div><button class="settings-nav" :class="{active:page==='settings'}" @click="navigate('settings')"><Settings :size="19"/>设置与备份<ChevronRight :size="16"/></button><div class="sidebar-footer"><span>TORRENT HARBOR</span><span>v{{data.version||appMeta.version}}</span></div></div>
    </aside>
    <div class="main-shell">
      <header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu" aria-label="打开菜单" @click="mobileNav=true"><Menu :size="21"/></button><span>工作空间</span><ChevronRight :size="14"/><b>{{title}}</b></div><div class="top-actions"><button class="icon-button theme-button" :aria-label="theme==='dark'?'切换浅色主题':'切换深色主题'" @click="toggleTheme"><Sun v-if="theme==='dark'" :size="19"/><Moon v-else :size="19"/></button><button class="mode-pill" :class="{real:!demo}" @click="switchMode"><FlaskConical v-if="demo" :size="14"/><ShieldCheck v-else :size="14"/>{{demo?'演示环境':'真实环境'}}<ChevronRight :size="12"/></button><span class="top-divider"></span><button class="avatar" aria-label="管理员设置" @click="navigate('settings')">H</button></div></header>
      <main>
        <div class="page-heading"><div><div class="eyebrow">{{page==='overview'?'YOUR BANDWIDTH, IN BALANCE':'TORRENT HARBOR / WORKSPACE'}}</div><h1>{{page==='overview'?'传输总览':title}}<span v-if="page==='overview'" class="heading-dot"></span></h1><p>{{page==='overview'?'所有下载器，一个视野。让带宽流向真正需要的地方。':page==='torrents'?'跨下载器查看任务，按站点、标签和规则找到每一个种子。':page==='pools'?'为一组种子划定共享预算，让每一份带宽各得其所。':page==='rules'?'用 Tracker、标签和时间，把你的习惯变成自动化。':page==='clients'?'连接你的 qBittorrent 和 Transmission。':page==='activity'?'每一次连接、配置和限速确认，都有迹可循。':'掌控运行方式，保管好你的工作空间。'}}</p></div><div class="heading-actions"><span class="date-label" v-if="page==='overview'"><Clock3 :size="14"/>{{date}}</span><button class="btn" @click="refresh" :disabled="loading"><RefreshCw :size="15" :class="{spin:loading}"/>刷新</button><button v-if="page==='overview'||page==='clients'" class="btn primary" @click="open('client')"><Plus :size="16"/>添加下载器</button><button v-if="page==='pools'" class="btn primary" @click="open('pool')"><Plus :size="16"/>新建带宽池</button><button v-if="page==='rules'" class="btn primary" @click="open('rule')"><Plus :size="16"/>新建规则</button></div></div>
        <div v-if="demo" class="environment-banner"><span class="banner-icon"><FlaskConical :size="16"/></span><span>你正在探索演示工作空间。<span class="banner-sub">下载器、站点及速率均为模拟数据。</span></span><button @click="switchMode">连接我的下载器<ArrowUpRight :size="14"/></button></div>
        <div v-if="conflicts.length||data.error" class="warning-banner"><AlertTriangle :size="17"/><span>{{data.error||`${conflicts.length} 项限速存在外部修改或未确认结果，相关提额已暂缓。请查看任务详情。`}}</span></div>

        <template v-if="page==='overview'">
          <div class="stats-grid"><article class="stat-card"><div class="stat-top"><span>总下载速度</span><span class="stat-icon blue"><ArrowDown :size="18"/></span></div><div class="stat-value">{{format(down,false)}}<small>{{down<1024?'B/s':down<M?'KiB/s':'MiB/s'}}</small></div><div class="stat-bottom"><span class="dot blue-dot"></span>{{torrents.filter(t=>t.state==='downloading').length}} 个任务正在下载<span class="stat-mark">DOWNLOAD</span></div></article><article class="stat-card"><div class="stat-top"><span>总上传速度</span><span class="stat-icon green"><ArrowUp :size="18"/></span></div><div class="stat-value">{{format(up,false)}}<small>{{up<1024?'B/s':up<M?'KiB/s':'MiB/s'}}</small></div><div class="stat-bottom"><span class="dot green-dot"></span>{{torrents.filter(t=>t.state==='seeding').length}} 个任务持续做种<span class="stat-mark">UPLOAD</span></div></article><article class="stat-card"><div class="stat-top"><span>在线下载器</span><span class="stat-icon purple"><Server :size="18"/></span></div><div class="stat-value">{{online}}<small class="fraction">/ {{clients.length}}</small></div><div class="stat-bottom"><span class="dot green-dot"></span>{{online===clients.length?'所有连接状态正常':`${clients.length-online} 个下载器未连接`}}<span class="stat-mark">CLIENTS</span></div></article><article class="stat-card"><div class="stat-top"><span>活跃种子</span><span class="stat-icon amber"><Layers3 :size="18"/></span></div><div class="stat-value">{{active}}<small class="fraction">/ {{torrents.length}}</small></div><div class="stat-bottom"><span class="dot amber-dot"></span>{{pools.length}} 个共享带宽池<span class="stat-mark">TORRENTS</span></div></article></div>
          <div class="overview-middle"><section class="panel traffic-panel"><div class="panel-head"><div><h2>带宽流动<span class="live-indicator">LIVE</span></h2><p>所有在线下载器的实时传输速率</p></div><div class="segmented"><button v-for="r in [5,30,60]" :class="{active:chartRange===r}" @click="chartRange=r">{{r===60?'1 小时':r+' 分钟'}}</button></div></div><div class="chart-legend"><span><i class="legend-line blue-line"></i>下载 <b>{{format(down)}}</b></span><span><i class="legend-line green-line"></i>上传 <b>{{format(up)}}</b></span><small v-if="demo">模拟数据</small><small v-else>自启动后采样</small></div><div class="chart-wrap"><div class="chart-axis"><span v-for="i in [1,2,3,4]">{{format(chartMax*(1-(i-1)/3),false)}}</span></div><div class="chart-plot"><div class="chart-grid"><i v-for="i in 4"></i></div><svg viewBox="0 0 850 185" preserveAspectRatio="none" role="img" aria-label="上传与下载速率曲线"><defs><linearGradient id="downFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#5587c2" stop-opacity=".16"/><stop offset="100%" stop-color="#5587c2" stop-opacity="0"/></linearGradient><linearGradient id="upFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#268b79" stop-opacity=".16"/><stop offset="100%" stop-color="#268b79" stop-opacity="0"/></linearGradient></defs><path :d="chartPath('download',true)" fill="url(#downFill)"/><path :d="chartPath('upload',true)" fill="url(#upFill)"/><path :d="chartPath('download')" stroke="#6092ce" stroke-width="2.5" fill="none" vector-effect="non-scaling-stroke"/><path :d="chartPath('upload')" stroke="#268b79" stroke-width="2.5" fill="none" vector-effect="non-scaling-stroke"/></svg><div v-if="!history.length" class="chart-empty">开始同步后，速率曲线会显示在这里</div><div class="chart-times"><span v-for="t in chartTimes">{{t}}</span></div></div></div><div class="chart-footer"><ShieldCheck :size="14"/>{{controlled?'按规则自动协调带宽，原生下载器上限仍然生效':'只读预览 · 已计算分配计划，尚未写入下载器'}}<button @click="toggleControl">{{controlled?'暂停接管':'开启接管'}}<ChevronRight :size="13"/></button></div></section>
          <section class="panel pools-compact"><div class="panel-head"><div><h2>共享带宽池</h2><p>按站点与标签，有序分配</p></div><button class="icon-button" aria-label="查看带宽池" @click="navigate('pools')"><ArrowUpRight :size="18"/></button></div><div v-if="!pools.length" class="empty-small">创建带宽池，开始分配共享额度。</div><div v-for="p in busyPools" class="pool-row"><div class="pool-row-title"><span class="pool-dot" :style="{background:p.color}"></span><strong>{{p.name}}</strong><small>{{poolStats(p.id).count}} 个种子</small></div><div class="pool-meter"><span :style="{width:Math.min(100,p.upload?poolStats(p.id).upload/p.upload*100:0)+'%',background:p.color}"></span></div><div class="pool-row-meta"><span><ArrowUp :size="12"/>{{format(poolStats(p.id).upload)}}</span><small>上限 {{format(p.upload)}}</small></div></div><button class="text-button pool-all" @click="navigate('pools')">管理所有带宽池<ChevronRight :size="14"/></button></section></div>
          <div class="section-heading"><h2>我的下载器<span>{{clients.length}}</span></h2><button class="text-button" @click="navigate('clients')">管理连接<ArrowUpRight :size="14"/></button></div><div class="client-grid"><article class="client-card" v-for="c in clients"><div class="client-top"><span class="client-logo" :class="c.type">{{c.type==='qb'?'qB':'Tr'}}</span><div><h3>{{c.name}}</h3><p>{{c.type==='qb'?'qBittorrent':'Transmission'}} <span>· {{c.version||'等待连接'}}</span></p></div><span class="connection-status" :class="{offline:!c.online}"><i></i>{{c.online?'在线':'离线'}}</span></div><div class="client-speeds"><div><span><ArrowDown :size="13"/>下载</span><strong>{{format(c.download)}}</strong></div><div><span><ArrowUp :size="13"/>上传</span><strong>{{format(c.upload)}}</strong></div><svg v-if="demo" class="client-wave" viewBox="0 0 100 35"><path :d="`M0 31 L8 29 L16 ${14+(c.torrentCount%5)} L23 25 L31 19 L39 24 L47 10 L55 20 L63 13 L71 18 L80 7 L89 12 L100 5`"/></svg></div><div class="client-footer"><span>{{c.torrentCount}} 个种子 <i>·</i> {{c.active}} 个活跃</span><button @click="clientFilter=c.id;navigate('torrents')">查看任务<ChevronRight :size="13"/></button></div></article><button v-if="!clients.length" class="empty-card" @click="open('client')"><Plus :size="26"/><strong>连接第一个下载器</strong><span>支持 QB 与 TR，多实例统一管理</span></button></div>
          <section class="panel active-panel"><div class="panel-head"><div><h2>正在传输</h2><p>此刻最活跃的任务</p></div><button class="text-button" @click="navigate('torrents')">查看全部种子<ArrowUpRight :size="14"/></button></div><div class="table-scroll"><table class="torrent-table compact"><thead><tr><th>种子名称</th><th>下载器 / 站点</th><th>状态</th><th>下载速度</th><th>上传速度</th><th></th></tr></thead><tbody><tr v-for="t in topTorrents" :key="t.key" @click="explain(t)"><td><div class="torrent-name"><span class="file-symbol"><Files :size="17"/></span><div><strong>{{t.name}}</strong><small>{{bytes(t.size)}}<span v-for="tag in t.tags.slice(0,2)" class="tiny-tag">{{tag}}</span></small></div></div></td><td><span class="client-inline">{{t.clientName}}</span><small class="secondary block">{{t.hosts[0]||'等待元数据'}}</small></td><td><span class="state-pill" :class="t.state">{{states[t.state]}}</span></td><td class="rate-blue">{{t.download?format(t.download):'—'}}</td><td class="rate-green">{{t.upload?format(t.upload):'—'}}</td><td><ChevronRight :size="15"/></td></tr><tr v-if="!topTorrents.length"><td colspan="6" class="empty-table">连接下载器后，传输任务会显示在这里。</td></tr></tbody></table></div></section>
        </template>

        <template v-if="page==='torrents'">
          <div class="filter-bar"><div class="search-field"><Search :size="17"/><input v-model="query" @input="listPage=1" placeholder="搜索名称、站点、标签…" aria-label="搜索种子"></div><select v-model="clientFilter" @change="listPage=1" aria-label="筛选下载器"><option value="">所有下载器</option><option v-for="c in clients" :value="c.id">{{c.name}}</option></select><select v-model="stateFilter" @change="listPage=1" aria-label="筛选状态"><option value="">所有状态</option><option v-for="(v,k) in states" :value="k">{{v}}</option></select><select v-model="hostFilter" @change="listPage=1" aria-label="筛选 Tracker"><option value="">所有 Tracker</option><option v-for="h in allHosts">{{h}}</option></select><select v-model="tagFilter" @change="listPage=1" aria-label="筛选标签"><option value="">所有标签</option><option v-for="t in allTags">{{t}}</option></select><select v-model="poolFilter" @change="listPage=1" aria-label="筛选带宽池"><option value="">所有带宽池</option><option v-for="p in pools" :value="p.id">{{p.name}}</option></select></div>
          <div v-if="selected.length" class="selection-bar"><span><CheckCheck :size="17"/>已选择 {{selected.length}} 个任务</span><button class="btn" @click="open('labels')"><Tag :size="14"/>本地标签</button><button class="btn" @click="open('override')"><Zap :size="14"/>临时调整</button><button class="text-button" @click="selected=[]">取消选择</button></div>
          <section class="panel"><div class="table-scroll"><table class="torrent-table full"><thead><tr><th><input type="checkbox" :checked="visible.length>0&&visible.every(t=>selected.includes(t.key))" @change="selectAll" aria-label="选择本页种子"></th><th>种子名称 / 进度</th><th>下载器 / Tracker</th><th>状态</th><th>下载 / 上传</th><th>目标限速 ↓ / ↑</th><th>主带宽池</th><th></th></tr></thead><tbody><tr v-for="t in visible" :key="t.key"><td><input type="checkbox" v-model="selected" :value="t.key" :aria-label="'选择 '+t.name"></td><td class="name-cell"><button class="name-link" @click="explain(t)">{{t.name}}</button><div class="progress-line"><i :style="{width:t.progress*100+'%'}"></i></div><small class="secondary">{{(t.progress*100).toFixed(1)}}% · {{bytes(t.size)}} <span v-for="tag in t.tags" class="tiny-tag" :class="{local:t.localTags.includes(tag)}">{{tag}}</span></small></td><td>{{t.clientName}}<small class="secondary block">{{t.hosts.join(', ')||'等待完整 Tracker'}}</small></td><td><span class="state-pill" :class="t.online?t.state:'error'">{{t.online?states[t.state]:'已失联'}}</span></td><td><span class="rate-blue block">↓ {{format(t.download)}}</span><span class="rate-green block">↑ {{format(t.upload)}}</span></td><td><span class="block">{{plan(t.key)?.managed?format(plan(t.key).download):'不接管'}}</span><span class="block secondary">{{plan(t.key)?.managed?format(plan(t.key).upload):'不接管'}}</span></td><td><span class="pool-tag">{{plan(t.key)?.managed?plan(t.key).poolName:'未分组'}}</span><small class="block secondary">{{plan(t.key)?.override?'临时设置有效':''}}</small></td><td><button class="icon-button" aria-label="查看限速解释" @click="explain(t)"><CircleHelp :size="17"/></button></td></tr><tr v-if="!visible.length"><td colspan="8" class="empty-table"><Files :size="28"/><p>没有找到符合条件的种子</p><span>尝试调整筛选，或连接一个下载器。</span></td></tr></tbody></table></div><div class="pagination"><span>共 {{filtered.length}} 个任务 · 每页 25 个</span><div><button class="btn small" :disabled="listPage===1" @click="listPage--">上一页</button><span>{{listPage}} / {{Math.max(1,Math.ceil(filtered.length/25))}}</span><button class="btn small" :disabled="listPage*25>=filtered.length" @click="listPage++">下一页</button></div></div></section>
          <p class="page-note"><CircleHelp :size="14"/>目标限速为规则计算结果。开启接管后才会写入；点击任务可查看下载器回读值。本地标签只保存在种子港。</p>
        </template>

        <template v-if="page==='pools'"><div class="pool-card-grid"><article class="panel pool-detail" v-for="p in pools"><div class="pool-detail-top"><span class="large-pool-icon" :style="{color:p.color,background:p.color+'14'}"><Waves :size="25"/></span><div><h2>{{p.name}}</h2><p>{{poolStats(p.id).count}} 个任务 · 权重 {{p.weight}}</p></div><button class="icon-button" aria-label="编辑带宽池" @click="open('pool',p)"><Pencil :size="16"/></button></div><div class="pool-direction" v-for="dir in ['upload','download']"><div><span><ArrowUp v-if="dir==='upload'" :size="14"/><ArrowDown v-else :size="14"/>{{dir==='upload'?'上传':'下载'}}</span><strong>{{format(poolStats(p.id)[dir])}}</strong></div><div class="pool-meter"><span :style="{width:Math.min(100,p[dir]?poolStats(p.id)[dir]/p[dir]*100:0)+'%',background:p.color}"></span></div><small>共享硬上限 {{format(p[dir])}}</small></div><div class="pool-detail-bottom"><button class="text-button" @click="poolFilter=p.id;navigate('torrents')">查看成员<ChevronRight :size="14"/></button><button class="icon-button danger-text" aria-label="删除带宽池" @click="confirmDelete('pools',p)"><Trash2 :size="15"/></button></div></article><button class="empty-card add-pool" @click="open('pool')"><Plus :size="26"/><strong>新的带宽安排</strong><span>创建共享池，再通过规则加入成员</span></button></div><div class="info-panel"><ShieldCheck :size="21"/><div><strong>共享的是整组预算，不是给每个种子重复设置同样的上限。</strong><p>同池成员可以跨 QB / TR。全局预算先分给各池，再按任务权重分配。首版采用硬上限，池内闲余按权重重新分配，不跨池突破上限。多个池命中时，仅最高优先级的主池参与共享记账。</p></div></div></template>

        <template v-if="page==='rules'"><div class="rule-summary"><span><span class="dot green-dot"></span>{{rules.filter(r=>r.enabled).length}} 条规则启用</span><span>数值越小，主池优先级越高</span><span>标签条件全部满足 · Tracker 条件任一满足</span></div><section class="panel rule-list"><article v-for="r in [...rules].sort((a,b)=>a.priority-b.priority)" class="rule-item"><div class="rule-priority">{{String(r.priority).padStart(2,'0')}}</div><div class="rule-content"><div class="rule-title"><h3>{{r.name}}</h3><span v-if="r.schedule" class="tiny-tag"><Clock3 :size="11"/>{{r.schedule.start}}–{{r.schedule.end}}</span></div><div class="rule-conditions"><span v-if="r.hosts.length"><Link2 :size="12"/>{{r.hosts.join(' / ')}}</span><span v-if="r.tags.length"><Tag :size="12"/>{{r.tags.join(' + ')}}</span><span v-if="r.clients.length"><Server :size="12"/>{{r.clients.map(id=>data.configuredClients.find(c=>c.id===id)?.name||id).join(' / ')}}</span><span v-if="!r.hosts.length&&!r.tags.length&&!r.clients.length">所有任务</span><span v-if="r.states.length">{{r.states.map(s=>states[s]).join(' / ')}}</span></div><div class="rule-effects"><span v-if="r.poolId"><Waves :size="12"/>{{pools.find(p=>p.id===r.poolId)?.name}}</span><span v-if="r.upload!=null">单种上传 ≤ {{format(r.upload)}}</span><span v-if="r.download!=null">单种下载 ≤ {{format(r.download)}}</span><span v-if="r.weight>1">任务权重 ×{{r.weight}}</span><small>命中 {{plans.filter(p=>p.matchedRules.some(x=>x.id===r.id)).length}} 个任务</small></div></div><div class="rule-actions"><button class="toggle" :class="{on:r.enabled}" @click="toggleRule(r)" :aria-label="(r.enabled?'停用':'启用')+r.name" :aria-pressed="r.enabled"><i></i></button><button class="icon-button" aria-label="编辑规则" @click="open('rule',r)"><Pencil :size="16"/></button><button class="icon-button danger-text" aria-label="删除规则" @click="confirmDelete('rules',r)"><Trash2 :size="16"/></button></div></article><div v-if="!rules.length" class="empty-table">创建第一条规则，让带宽自动分配。</div></section><div class="info-panel"><Eye :size="22"/><div><strong>先看影响，再让规则运行。</strong><p>编辑规则时可以预览命中的种子和目标限速。附加单种上限取所有命中规则中更严格的值；临时提权也遵守这些上限。时间段按 {{data.settings.timezone}} 执行，跨午夜归属于开始日。</p></div></div></template>

        <template v-if="page==='clients'"><div class="client-management"><article class="panel client-manage-card" v-for="c in data.configuredClients.filter(c=>Boolean(c.demo)===demo)"><div class="client-top"><span class="client-logo" :class="c.type">{{c.type==='qb'?'qB':'Tr'}}</span><div><h3>{{c.name}}</h3><p>{{c.type==='qb'?'qBittorrent':'Transmission'}} · {{c.demo?'模拟连接':c.url}}</p></div><span class="state-pill" :class="clients.find(x=>x.id===c.id)?.online?'seeding':'error'">{{clients.find(x=>x.id===c.id)?.online?'已连接':c.enabled?'未连接':'已停用'}}</span></div><div class="native-info"><div><span>原生上传上限</span><strong>{{format(clients.find(x=>x.id===c.id)?.native?.upload)}}</strong></div><div><span>原生下载上限</span><strong>{{format(clients.find(x=>x.id===c.id)?.native?.download)}}</strong></div><div><span>替代限速模式</span><strong>{{clients.find(x=>x.id===c.id)?.native?.alternative?'已开启':'未开启'}}</strong></div></div><p class="client-error" v-if="clients.find(x=>x.id===c.id)?.error">{{clients.find(x=>x.id===c.id).error}}</p><div class="client-footer"><span>{{c.demo?'演示连接不会访问网络':c.hasPassword?'连接密码已加密保存':'未保存连接密码'}}</span><div v-if="!c.demo"><button class="text-button" @click="open('client',c)">编辑连接</button><button class="icon-button danger-text" aria-label="移除下载器" @click="confirmDelete('clients',c)"><Trash2 :size="15"/></button></div></div></article><button class="empty-card" @click="open('client')"><Plus :size="26"/><strong>添加下载器</strong><span>连接本地 NAS 或远程服务器上的 QB / TR</span></button></div><div v-if="demo&&data.configuredClients.some(c=>!c.demo)" class="info-panel"><Server :size="22"/><div><strong>真实下载器配置已保存。</strong><p>切换到真实环境后会开始只读同步，演示任务与真实任务分开显示。</p></div></div></template>

        <template v-if="page==='activity'"><section class="panel activity-list"><article v-for="e in events" :key="e.id"><span class="event-icon" :class="e.level"><CheckCircle2 v-if="e.level==='success'" :size="18"/><AlertTriangle v-else-if="['warning','error'].includes(e.level)" :size="18"/><Activity v-else :size="18"/></span><div><h3>{{e.title}}</h3><p>{{e.detail}}</p></div><time>{{time(e.time)}}<small>{{new Date(e.time).toLocaleDateString('zh-CN',{timeZone:data.settings.timezone})}}</small></time></article></section><p class="page-note">保留最近 2,000 条记录，界面展示最近 150 条。速率采样保留 7 天。</p></template>

        <Updates v-if="page==='updates'" :api="api" :notify="notify" :controlled="controlled" :managed="data.managed.length"/>
        <template v-if="page==='settings'"><div class="settings-grid"><section class="panel settings-panel"><div class="panel-head"><div><h2>运行与接管</h2><p>你决定什么时候将计划变成动作。</p></div><ShieldCheck :size="21"/></div><div class="setting-row"><div><strong>运行环境</strong><p>{{demo?'独立演示数据，不连接真实下载器':'真实下载器，仅连接已启用的配置'}}</p></div><button class="btn" @click="switchMode">{{demo?'切换真实环境':'切换演示环境'}}</button></div><div class="setting-row"><div><strong>自动限速接管</strong><p>{{controlled?'后台持续执行规则，关闭网页后继续运行':'仅计算目标值，不写入下载器'}}</p></div><button class="toggle" :class="{on:controlled}" @click="toggleControl" aria-label="自动限速接管" :aria-pressed="controlled"><i></i></button></div><div class="setting-row"><div><strong>释放接管并恢复</strong><p>仅恢复仍等于本程序写入值的设置，保留外部修改。</p></div><button class="btn" @click="modal={kind:'release'};modalError=''">释放接管</button></div><div class="setting-foot"><AlertTriangle :size="15"/>暂停接管或停止程序后，下载器保留最后的限速值。需要恢复时请使用“释放接管”。</div></section><section class="panel settings-panel"><div class="panel-head"><div><h2>带宽与调度</h2><p>上传、下载分别安排，预算仅覆盖受管任务。</p></div><Waves :size="21"/></div><div class="setting-metrics"><div><span>受管上传总预算</span><strong>{{format(data.settings.uploadBudget)}}</strong></div><div><span>受管下载总预算</span><strong>{{format(data.settings.downloadBudget)}}</strong></div><div><span>状态同步</span><strong>{{data.settings.pollSeconds}} 秒</strong></div><div><span>限额调度</span><strong>{{data.settings.controlSeconds}} 秒</strong></div></div><div class="setting-row"><div><strong>计划时区</strong><p>{{data.settings.timezone}}</p></div><button class="btn" @click="editSettings">编辑设置</button></div><div class="setting-foot">跨多条宽带时，请按出口分别部署实例。原生总限速、分组与局域网设置仍会影响实际效果。</div></section><section class="panel settings-panel"><div class="panel-head"><div><h2>配置与备份</h2><p>你的规则与连接，留在自己的设备上。</p></div><Download :size="21"/></div><div class="setting-row"><div><strong>导出配置</strong><p>导出下载器地址、池与规则，不含密码和恢复基线。</p></div><button class="btn" @click="exportConfig">导出 JSON</button></div><div class="setting-row"><div><strong>完整备份</strong><p>停止服务后，备份整个 data 目录，包括数据库与 secret.key。</p></div><span class="tiny-tag">本地持久化</span></div></section><section class="panel settings-panel"><div class="panel-head"><div><h2>管理访问</h2><p>保护你的下载器连接与管理操作。</p></div><LockKeyhole :size="21"/></div><div class="setting-row"><div><strong>管理密码</strong><p>会话在服务重启后失效。</p></div><button class="btn" @click="modal={kind:'password'};form={current:'',password:''};modalError=''">修改密码</button></div><div class="setting-row"><div><strong>退出工作空间</strong><p>后台调度继续运行。</p></div><button class="btn" @click="logout"><LogOut :size="14"/>退出登录</button></div></section></div></template>
        <footer class="main-footer"><span>一切有序，各得其所。</span><span><span class="dot green-dot"></span>{{demo?'演示数据':'本地连接'}} · {{data.syncing?'正在同步':`更新于 ${time(data.now)}`}}</span></footer>
      </main>
    </div>

    <div v-if="modal" class="modal-backdrop" @click.self="!saving&&(modal=null)"><section class="modal" :class="{'modal-wide':['rule','explain'].includes(modal.kind)}" role="dialog" aria-modal="true" :aria-label="modalTitle"><div class="modal-head"><div><span class="eyebrow">TORRENT HARBOR</span><h2>{{modalTitle}}</h2></div><button class="icon-button" aria-label="关闭对话框" :disabled="saving" @click="modal=null"><X :size="21"/></button></div><form @submit.prevent="saveModal">
      <div class="modal-body">
        <template v-if="modal.kind==='client'"><p class="form-intro">通过官方 WebUI / RPC 接口连接。测试连接与保存配置均不会修改限速。</p><label>连接名称<input v-model="form.name" placeholder="例如：NAS 主力下载器" required maxlength="100"></label><div class="form-two"><label>下载器类型<select v-model="form.type"><option value="qb">qBittorrent</option><option value="tr">Transmission</option></select></label><label>连接状态<select v-model="form.enabled"><option :value="true">启用</option><option :value="false">停用</option></select></label></div><label>服务地址<input v-model="form.url" type="url" :placeholder="form.type==='qb'?'http://192.168.1.10:8080':'http://192.168.1.10:9091'" required></label><small class="field-note">{{form.type==='qb'?'填写 WebUI 根地址，支持反向代理子路径。':'填写根地址或完整的 /transmission/rpc 地址。'}}</small><div class="form-two"><label>用户名<input v-model="form.username" autocomplete="off" placeholder="可留空"></label><label>密码<input v-model="form.password" type="password" autocomplete="new-password" :placeholder="form.hasPassword?'留空保留已保存密码':'连接密码'"></label></div><div class="form-callout"><LockKeyhole :size="16"/>连接密码使用持久化密钥加密保存，不会返回前端。</div><div v-if="preview?.connection" class="preview-success"><CheckCircle2 :size="17"/>{{preview.connection}}</div></template>
        <template v-if="modal.kind==='pool'"><label>带宽池名称<input v-model="form.name" required maxlength="100" placeholder="例如：A 站 · 日常下载"></label><div class="form-two"><label>共享上传上限 · MiB/s<input v-model="form.upload" type="number" min="0.001" step="any" placeholder="留空不设池上限"></label><label>共享下载上限 · MiB/s<input v-model="form.download" type="number" min="0.001" step="any" placeholder="留空不设池上限"></label></div><div class="form-two"><label>全局分配权重<input v-model="form.weight" type="number" min="1" max="100" required></label><label>标识颜色<input v-model="form.color" type="color"></label></div><div class="form-callout"><Waves :size="17"/>创建后，通过规则把 Tracker 或标签对应的任务加入池。池上限是硬上限，全局预算不足时按池权重分配。</div></template>
        <template v-if="modal.kind==='rule'"><div class="form-two"><label>规则名称<input v-model="form.name" required maxlength="100" placeholder="例如：A 站保种任务"></label><label>主池优先级 · 越小越优先<input v-model="form.priority" type="number" min="0" max="9999" required></label></div><div class="form-section-title"><span>01</span>选择哪些种子<small>不同条件之间同时满足；留空表示不限</small></div><label>Tracker 主机名<input v-model="form.hosts" placeholder="tracker.example.org, *.example.net"></label><small class="field-note">多个主机名任一命中；使用完整 Tracker 列表，不包含路径或 passkey。</small><div class="form-two"><label>标签 · 多个标签需全部满足<input v-model="form.tags" placeholder="保种, 电影"></label><label>QB 分类<input v-model="form.category" placeholder="可留空，只读匹配"></label></div><fieldset class="field-group"><legend>下载器范围</legend><div class="checkbox-group"><label v-for="c in data.configuredClients" class="check-label"><input type="checkbox" v-model="form.clients" :value="c.id">{{c.name}}<small>{{c.demo?'演示':'真实'}}</small></label></div></fieldset><fieldset class="field-group"><legend>任务状态</legend><div class="checkbox-group"><label v-for="(v,k) in states" class="check-label"><input type="checkbox" v-model="form.states" :value="k">{{v}}</label></div></fieldset><div class="form-section-title"><span>02</span>怎样安排带宽</div><label>加入主带宽池<select v-model="form.poolId"><option value="">不指定池 · 只应用单种限制 / 权重</option><option v-for="p in pools" :value="p.id">{{p.name}}</option></select></label><div class="form-two"><label>单种上传上限 · MiB/s<input v-model="form.upload" type="number" min="0.001" step="any" placeholder="留空不增加单种上限"></label><label>单种下载上限 · MiB/s<input v-model="form.download" type="number" min="0.001" step="any" placeholder="留空不增加单种上限"></label></div><div class="form-two"><label>任务分配权重<input v-model="form.weight" type="number" min="1" max="100" required></label><label>规则状态<select v-model="form.enabled"><option :value="true">启用</option><option :value="false">停用</option></select></label></div><div class="form-section-title"><span>03</span>什么时候生效</div><label class="check-label"><input type="checkbox" v-model="form.scheduled">只在指定时间段生效 <small>{{data.settings.timezone}}</small></label><template v-if="form.scheduled"><div class="form-two"><label>开始时间<input v-model="form.start" type="time" required></label><label>结束时间<input v-model="form.end" type="time" required></label></div><div class="checkbox-group"><label v-for="(v,k) in ['日','一','二','三','四','五','六']" class="check-label"><input type="checkbox" v-model="form.days" :value="k">周{{v}}</label></div><small class="field-note">不选星期表示每天；跨午夜归属于开始日。</small></template><div v-if="preview?.matches" class="preview-box"><h3><Eye :size="16"/>预览：命中 {{preview.matches.length}} / {{preview.total}} 个任务</h3><div v-for="p in preview.matches.slice(0,8)"><span>{{p.name}}</span><small>↑ {{format(p.upload)}} · ↓ {{format(p.download)}}</small></div><p v-if="preview.matches.length>8">另有 {{preview.matches.length-8}} 个任务</p><p v-if="!preview.matches.length">当前任务没有命中，保存后仍会对未来匹配的任务生效。</p></div></template>
        <template v-if="modal.kind==='labels'"><p class="form-intro">为选中的 {{selected.length}} 个任务替换本地标签，原生标签保持独立。</p><label>本地标签<input v-model="form.tags" placeholder="例如：保种, 纪录片"></label><small class="field-note">用逗号分隔；留空清除本地标签。规则可以同时匹配本地与原生标签。</small></template>
        <template v-if="modal.kind==='override'"><p class="form-intro">为 {{selected.length}} 个任务临时调整权重或收紧上限，到期自动恢复规则。</p><div class="form-two"><label>临时上传上限 · MiB/s<input v-model="form.upload" type="number" min="0.001" step="any" placeholder="留空不增加限制"></label><label>临时下载上限 · MiB/s<input v-model="form.download" type="number" min="0.001" step="any" placeholder="留空不增加限制"></label></div><div class="form-two"><label>临时权重<input v-model="form.weight" type="number" min="1" max="100" required></label><label>有效分钟数<input v-model="form.minutes" type="number" min="1" max="1440" required></label></div><div class="form-callout"><Zap :size="17"/>提高权重可争取更多池内份额，仍遵守池硬上限和单种规则上限。</div></template>
        <template v-if="modal.kind==='explain'&&explanation"><div class="explain-name"><Files :size="22"/><div><h3>{{explanation.name}}</h3><p>{{explanation.clientName}} · {{explanation.hosts.join(' / ')||'等待 Tracker 元数据'}}</p></div></div><div class="explain-metrics"><div><span>当前上传</span><strong>{{format(explanation.upload)}}</strong></div><div><span>当前下载</span><strong>{{format(explanation.download)}}</strong></div><div><span>主带宽池</span><strong>{{plan(explanation.key)?.managed?plan(explanation.key).poolName:'不接管'}}</strong></div></div><table class="explain-table"><thead><tr><th>控制层级</th><th>上传</th><th>下载</th></tr></thead><tbody><tr><td>规则 / 池分配目标</td><td>{{format(plan(explanation.key)?.upload)}}</td><td>{{format(plan(explanation.key)?.download)}}</td></tr><tr><td>下载器当前回读</td><td>{{format(explanation.uploadLimit)}}</td><td>{{format(explanation.downloadLimit)}}</td></tr><tr><td>最近确认写入值</td><td>{{data.managed.some(m=>m.key===explanation.key&&m.direction==='upload')?format(data.managed.find(m=>m.key===explanation.key&&m.direction==='upload').last):'尚未写入'}}</td><td>{{data.managed.some(m=>m.key===explanation.key&&m.direction==='download')?format(data.managed.find(m=>m.key===explanation.key&&m.direction==='download').last):'尚未写入'}}</td></tr></tbody></table><p class="field-note">回读更新时间 {{time(explanation.updated)}}。没有确认记录时，“最近确认写入值”不代表已执行。原生全局、替代限速和 TR 既有分组也会约束速度。</p><div v-if="plan(explanation.key)?.execution" class="form-callout">最近调度：{{plan(explanation.key).execution}}</div><div class="form-section-title">命中的规则</div><div class="matched-rule" v-for="r in plan(explanation.key)?.matchedRules"><Check :size="14"/>{{r.name}}</div><p v-if="!plan(explanation.key)?.matchedRules.length" class="secondary">没有命中自动化规则。</p><ul class="reason-list"><li v-for="r in plan(explanation.key)?.reasons">{{r}}</li></ul><div v-if="data.managed.some(m=>m.key===explanation.key&&m.conflict)" class="form-callout warning"><AlertTriangle :size="18"/><div>存在外部修改或未确认写入。重新接管将以当前实际值继续调度，并保留最初恢复基线。<button type="button" class="text-button" @click="reclaim(explanation.key)" :disabled="saving">重新接管此任务<ChevronRight :size="13"/></button></div></div><div v-if="plan(explanation.key)?.override" class="form-callout"><Clock3 :size="17"/><div>临时设置在 {{time(plan(explanation.key).override.expires)}} 到期。<button type="button" class="text-button" @click="clearOverride(explanation.key)">取消临时设置</button></div></div></template>
        <template v-if="modal.kind==='mode'"><div class="confirm-visual"><FlaskConical v-if="!demo" :size="34"/><Server v-else :size="34"/></div><p class="confirm-copy">{{demo?'切换后开始读取你已保存的真实下载器。自动接管会保持关闭，先查看分组和限速计划，再决定是否开启。':'切换后只显示独立演示任务，不连接真实下载器。'}}</p><div class="form-callout">如当前存在已接管设置，请先在设置页“释放接管并恢复”，再切换环境。</div></template>
        <template v-if="modal.kind==='control'"><div class="confirm-visual"><ShieldCheck :size="35"/></div><p class="confirm-copy">{{demo?'将在演示任务上模拟执行限速，真实下载器不会受到影响。':'将按已启用规则持续修改真实下载器的单种限速。关闭网页后，后台仍会运行。'}}</p><div class="form-callout">{{plans.filter(p=>p.managed).length}} 个任务命中规则。全局预算只覆盖受管任务；未命中的任务保留原生设置。请先在种子详情或规则预览中检查目标值。</div></template>
        <template v-if="modal.kind==='release'"><p class="confirm-copy">停止自动接管，并尝试恢复当前环境中各任务接管前的限速。</p><div class="form-callout">仅在当前值仍等于本程序最后确认写入值时恢复。失联、外部修改或写入未确认的项会保留，并显示待处理状态。</div></template>
        <template v-if="modal.kind==='delete'"><p class="confirm-copy">删除“{{modal.name}}”？</p><p class="secondary">删除规则后，相关任务将在接管运行的下一轮重新计算。删除下载器前，需要先释放接管。</p></template>
        <template v-if="modal.kind==='settings'"><p class="form-intro">预算仅覆盖命中规则或临时设置的任务。建议为网络波动保留余量。</p><div class="form-two"><label>受管上传总预算 · MiB/s<input v-model="form.uploadBudget" type="number" min="0.001" step="any" placeholder="留空不设总预算"></label><label>受管下载总预算 · MiB/s<input v-model="form.downloadBudget" type="number" min="0.001" step="any" placeholder="留空不设总预算"></label></div><div class="form-two"><label>状态同步间隔 · 秒<input v-model="form.pollSeconds" type="number" min="3" max="300" required></label><label>限速调度间隔 · 秒<input v-model="form.controlSeconds" type="number" min="10" max="600" required></label></div><label>计划时区<input v-model="form.timezone" required placeholder="Asia/Shanghai"></label><label class="check-label demand-option"><input type="checkbox" v-model="form.demandAware">按需求回收闲置额度，保留探测份额</label><small class="field-note">开启时按实测速率估计需求，持续触顶的任务逐步提额；关闭时采用固定加权分配。</small></template>
        <template v-if="modal.kind==='password'"><label>当前密码<input v-model="form.current" type="password" autocomplete="current-password" required maxlength="256"></label><label>新密码<input v-model="form.password" type="password" autocomplete="new-password" required minlength="10" maxlength="256"></label></template>
        <p v-if="modalError" class="form-error" role="alert">{{modalError}}</p>
      </div><div class="modal-footer"><button v-if="modal.kind==='client'" type="button" class="btn" @click="testClient" :disabled="saving||!form.url"><Wifi :size="15"/>测试连接</button><button v-if="modal.kind==='rule'" type="button" class="btn" @click="previewRule" :disabled="saving"><Eye :size="15"/>预览影响</button><div class="footer-spacer"></div><button type="button" class="btn" @click="modal=null" :disabled="saving">{{modal.kind==='explain'?'关闭':'取消'}}</button><button v-if="modal.kind==='release'" type="button" class="btn primary" @click="release" :disabled="saving">{{saving?'正在恢复…':'释放并恢复'}}</button><button v-else-if="modal.kind!=='explain'" class="btn" :class="modal.kind==='delete'?'danger':'primary'" :disabled="saving">{{saving?'处理中…':modal.kind==='delete'?'确认删除':modal.kind==='control'?'开启接管':modal.kind==='mode'?'确认切换':'保存设置'}}<Check v-if="!saving&&!['delete','control','mode'].includes(modal.kind)" :size="15"/></button></div>
    </form></section></div>
    <div v-if="toast" class="toast" :class="{error:toast.error}" role="status"><AlertTriangle v-if="toast.error" :size="18"/><CheckCircle2 v-else :size="18"/>{{toast.message}}</div>
  </div>
</template>
